const pb = global.get("pb");
const conns = pb.getActiveConnections();

if (conns.length === 0) {
    return null;
}

msg.connection = conns[0];
return msg;

const conn = msg.connection;

msg.headers = {
    'x-api-key': conn.wasos.api.key
};

msg.url = global.get("pb").getBaseUrl("wasos") + "/api/chat/messages/" + conn.wasos.chatroom_name + "?limit=5";

return msg;
